#!/system/bin/sh

set -u

# çµ‚ç«¯ App (å¦‚ MT ç®¡ç†å™¨) å¯èƒ½å¸¶æœ‰è‡ªå·±çš„ LD_LIBRARY_PATH / LD_PRELOADï¼Œ
# æœƒè®“ rish å•Ÿå‹•çš„ app_process è¼‰å…¥éŒ¯èª¤ç‰ˆæœ¬çš„ libcrypto è€Œå ±
# "cannot locate symbol OpenSSL_add_all_algorithms"ï¼Œæ‰€ä»¥å…ˆæ¸…æŽ‰ã€‚
unset LD_LIBRARY_PATH LD_PRELOAD 2>/dev/null || true

# çµ•å°è·¯å¾‘ï¼šé¿å…ç‰¹æ¬Š shell å·¥ä½œç›®éŒ„ä¸åŒè€Œæ‰¾ä¸åˆ°è‡ªå·±
SELF_DIR="$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)" || exit 19
SELF="$SELF_DIR/$(basename -- "$0")"

RISH="${RISH:-}"   # ç©º = è‡ªå‹•æœå°‹ï¼›ä¹Ÿå¯æ‰‹å‹•æŒ‡å®š: RISH=/path/to/rish sh MB.sh
TARGET="imgui-v17"
RUNTIME_PREFIX="${RUNTIME_PREFIX:-/data/local/tmp/imgui-mb-vulkan-runtime-}"
MAX_WAIT=30

# æ‰“åŒ…æ™‚ç”± build è…³æœ¬å¡«å…¥ header å¤§å°ï¼ˆ8 å­—å…ƒå¯¬åº¦ï¼Œå‹¿æ‰‹å‹•ä¿®æ”¹ï¼‰
PAYLOAD_OFFSET=$((    8250))

# ============================================================
# è‡ªå‹•æœå°‹ rish
# ä¸åŒæ‰‹æ©Ÿ / ä¸åŒçµ‚ç«¯ App (MT ç®¡ç†å™¨ã€Termuxã€å…¶ä»–) çš„ rish ä½ç½®éƒ½ä¸ä¸€æ¨£ï¼Œ
# æ‰€ä»¥ä¾åºå˜—è©¦ï¼šä½¿ç”¨è€…æŒ‡å®š -> PATH -> ç›®å‰çµ‚ç«¯ App è‡ªå·±çš„è³‡æ–™ç›®éŒ„ ->
# å¸¸è¦‹ä½ç½® -> è…³æœ¬æ—é‚Š -> å…±ç”¨å„²å­˜ç©ºé–“ï¼Œç¬¬ä¸€å€‹ã€ŒçœŸçš„èƒ½åŸ·è¡Œã€çš„å°±æŽ¡ç”¨ã€‚
# ============================================================

RISH_TRIED="|"
RISH_FOUND_FILE=0

rish_works()
{
    [ -n "${1:-}" ] || return 1
    [ -f "$1" ] || return 1
    case "$RISH_TRIED" in *"|$1|"*) return 1 ;; esac
    RISH_TRIED="${RISH_TRIED}$1|"
    RISH_FOUND_FILE=1
    if sh "$1" -c 'echo OK' >/dev/null 2>&1; then
        RISH="$1"
        return 0
    fi
    return 1
}

# å¾žç›®å‰è¡Œç¨‹å¾€ä¸Šæ‰¾çˆ¶è¡Œç¨‹ï¼Œæ”¶é›†å¯èƒ½çš„ã€Œçµ‚ç«¯ App å¥—ä»¶åã€(ä¾‹å¦‚ bin.mt.plus)
collect_pkgs()
{
    PKGS=""
    PP="$$"
    N=0
    while [ "$N" -lt 8 ] && [ -n "$PP" ] && [ "$PP" -gt 1 ] 2>/dev/null; do
        C="$(tr '\0' ' ' < "/proc/$PP/cmdline" 2>/dev/null | cut -d' ' -f1)"
        C="${C%%:*}"
        case "$C" in
            ''|*/*|*' '*) ;;
            *.*) PKGS="$PKGS $C" ;;
        esac
        PP="$(grep '^PPid:' "/proc/$PP/status" 2>/dev/null | tr -dc '0-9')"
        N=$((N + 1))
    done
}

find_rish()
{
    # 1) ä½¿ç”¨è€…æ‰‹å‹•æŒ‡å®š
    if [ -n "${RISH:-}" ]; then
        rish_works "$RISH" && return 0
        RISH=""
    fi

    # 2) PATH è£¡çš„ rish
    P="$(command -v rish 2>/dev/null || true)"
    rish_works "$P" && return 0

    # 3) ç›®å‰çµ‚ç«¯ App è‡ªå·±çš„è³‡æ–™ç›®éŒ„ (è‡ªå·±çš„è³‡æ–™å¤¾ä¸€å®šè®€å¾—åˆ°)
    collect_pkgs
    for K in $PKGS bin.mt.plus bin.mt.plus.canary com.termux; do
        for B in "/data/user/0/$K" "/data/data/$K"; do
            [ -d "$B" ] || continue
            for C in \
                "$B/files/rish/rish" "$B/files/rish" "$B/files/home/rish" \
                "$B/files/usr/bin/rish" "$B/files/term/rish" "$B/rish"
            do
                rish_works "$C" && return 0
            done
            for C in $(find "$B" -maxdepth 6 -name rish -type f 2>/dev/null); do
                rish_works "$C" && return 0
            done
        done
    done

    # 4) $HOME / $PREFIX (Termux é¢¨æ ¼)
    for C in "${HOME:-/nonexistent}/rish" "${HOME:-/nonexistent}/bin/rish" \
             "${PREFIX:-/nonexistent}/bin/rish"
    do
        rish_works "$C" && return 0
    done

    # 5) è…³æœ¬æ—é‚Š
    for C in "$SELF_DIR/rish" "$SELF_DIR/rish/rish" "$SELF_DIR/../rish"; do
        rish_works "$C" && return 0
    done

    # 6) å…±ç”¨å„²å­˜ç©ºé–“ (Shizuku åŒ¯å‡º rish æ™‚å¸¸æ”¾åœ¨é€™è£¡)
    for R in /storage/emulated/0 /sdcard; do
        [ -d "$R" ] || continue
        for C in "$R/rish" "$R/Download/rish" "$R/Documents/rish" \
                 "$R/Download/Shizuku/rish" "$R/Shizuku/rish"
        do
            rish_works "$C" && return 0
        done
        for C in $(find "$R" -maxdepth 3 -name rish -type f 2>/dev/null); do
            rish_works "$C" && return 0
        done
    done

    return 1
}

# ============================================================
# Privilege Detection: root / adb shell / su / Shizuku(rish)
# ============================================================

PRIV_MODE=""
MY_UID="$(id -u 2>/dev/null || echo 99999)"

if [ "$MY_UID" = "0" ] || [ "$MY_UID" = "2000" ]; then
PRIV_MODE="direct"
elif command -v su >/dev/null 2>&1 &&
[ "$(su -c 'id -u' 2>/dev/null | tr -d '\r\n')" = "0" ]; then
PRIV_MODE="su"
elif find_rish; then
PRIV_MODE="rish"
else
echo "[!] æ‰¾ä¸åˆ°å¯ç”¨çš„ç‰¹æ¬Šç’°å¢ƒ (éœ€è¦ root / adb shell / Shizuku å…¶ä¸­ä¹‹ä¸€)" >&2
if [ "$RISH_FOUND_FILE" = "0" ]; then
echo " - è‡ªå‹•æœå°‹ä¸åˆ° rishï¼šè«‹å…ˆåœ¨ Shizuku App çš„ã€Œåœ¨çµ‚ç«¯æ‡‰ç”¨ä¸­ä½¿ç”¨ Shizukuã€åŒ¯å‡º rishï¼Œ" >&2
echo "   æ”¾åˆ°æœ¬çµ‚ç«¯ App å¯è®€çš„ä½ç½® (ä¾‹å¦‚è…³æœ¬æ—é‚Šæˆ– /storage/emulated/0/)ï¼Œ" >&2
echo "   æˆ–æ‰‹å‹•æŒ‡å®š: RISH=/path/to/rish sh \"$SELF\"" >&2
else
echo " - æ‰¾åˆ° rish ä½†ç„¡æ³•åŸ·è¡Œï¼šè«‹ç¢ºèª Shizuku å·²å•Ÿå‹•ï¼Œä¸”å·²æŽˆæ¬Šçµ¦æœ¬çµ‚ç«¯ App" >&2
fi
exit 21
fi

run_priv()
{
case "$PRIV_MODE" in
direct) sh -c "$1" ;;
su) su -c "$1" ;;
rish) sh "$RISH" -c "$1" ;;
esac
}


# ============================================================
# Runtime Cleanup
# ============================================================

RUN_DIR=""

cleanup_runtime()
{
if [ -n "${RUN_DIR:-}" ]; then
run_priv "rm -rf '$RUN_DIR' 2>/dev/null || true" \
>/dev/null 2>&1 || true
fi
}

cleanup_old_instances()
{
PIDS="$(run_priv "pidof '$TARGET' 2>/dev/null" 2>/dev/null || true)"

if [ -z "$PIDS" ]; then
PIDS="$(
run_priv \
"ps -A 2>/dev/null | awk '\$NF == \"$TARGET\" {print \$2}'" \
2>/dev/null || true
)"
fi

if [ -n "$PIDS" ]; then
for PID in $PIDS; do
case "$PID" in
''|*[!0-9]*) continue ;;
esac
run_priv "kill -TERM '$PID' 2>/dev/null || true" \
>/dev/null 2>&1 || true
done

I=0
STILL=""

while [ "$I" -lt "$MAX_WAIT" ]; do
STILL=""

for PID in $PIDS; do
case "$PID" in
''|*[!0-9]*) continue ;;
esac
if run_priv "kill -0 '$PID' 2>/dev/null" \
>/dev/null 2>&1; then
STILL="$STILL $PID"
fi
done

[ -z "$STILL" ] && break

I=$((I + 1))
sleep 0.1
done

for PID in $STILL; do
run_priv "kill -KILL '$PID' 2>/dev/null || true" \
>/dev/null 2>&1 || true
done
fi

run_priv "rm -rf '${RUNTIME_PREFIX}'* 2>/dev/null || true" \
>/dev/null 2>&1 || true
}

cleanup_old_instances

# ============================================================
# Extract ELF
# ============================================================

RUN_DIR="${RUNTIME_PREFIX}$$"
TMP_ELF="$RUN_DIR/imgui-v17"

trap cleanup_runtime EXIT INT TERM HUP

TOTAL_SIZE="$(wc -c < "$SELF" | tr -d ' \r\n')"
EXPECT_SIZE=$((TOTAL_SIZE - PAYLOAD_OFFSET))

if [ "$EXPECT_SIZE" -le 1024 ]; then
echo "[!] MB.sh å·²ææ¯€æˆ–ä¸å®Œæ•´ (å¤§å°ç•°å¸¸)" >&2
exit 22
fi

if ! run_priv "
rm -rf '$RUN_DIR'
mkdir -p '$RUN_DIR' || exit 1
tail -c '+$((PAYLOAD_OFFSET + 1))' '$SELF' > '$TMP_ELF' || exit 2
chmod 755 '$TMP_ELF'
" >/dev/null 2>&1; then
echo "[!] è§£å‡º ELF å¤±æ•— (ç‰¹æ¬Šç«¯è®€ä¸åˆ° $SELFï¼Œæˆ– /data/local/tmp ç„¡æ³•å¯«å…¥)" >&2
echo " è«‹æŠŠ MB.sh æ”¾åœ¨ /storage/emulated/0/ ä¸‹å†è©¦" >&2
exit 24
fi

ACTUAL_SIZE="$(run_priv "wc -c < '$TMP_ELF'" 2>/dev/null | tr -d ' \r\n')"

if [ "$ACTUAL_SIZE" != "$EXPECT_SIZE" ]; then
echo "[!] ELF å¤§å°ä¸ç¬¦ (æœŸæœ› $EXPECT_SIZE, å¯¦éš› ${ACTUAL_SIZE:-?})" >&2
exit 29
fi

# ============================================================
# Validate Extracted ELF
# ============================================================

ELF_HEX="$(
run_priv "od -An -tx1 -N24 '$TMP_ELF' 2>/dev/null" |
tr -d ' \n\r\t'
)"

MAGIC="$(printf '%s' "$ELF_HEX" | cut -c1-8)"
CLASS="$(printf '%s' "$ELF_HEX" | cut -c9-10)"
DATA="$(printf '%s' "$ELF_HEX" | cut -c11-12)"
MACHINE="$(printf '%s' "$ELF_HEX" | cut -c37-40)"

if [ "$MAGIC" != "7f454c46" ]; then
echo "[!] ä¸æ˜¯æœ‰æ•ˆçš„ ELF" >&2
exit 25
fi

if [ "$CLASS" != "02" ]; then
echo "[!] ELF ä¸æ˜¯ 64 ä½" >&2
exit 26
fi

if [ "$DATA" != "01" ]; then
echo "[!] ELF ä¸æ˜¯ little-endian" >&2
exit 27
fi

if [ "$MACHINE" != "b700" ]; then
echo "[!] æ­¤ ELF ç‚º AArch64ï¼Œæœ¬è¨­å‚™æž¶æ§‹ä¸ç¬¦" >&2
exit 28
fi

# ============================================================
# Launch Native ELF
# ============================================================

run_priv "
export LD_LIBRARY_PATH='$RUN_DIR:/system/lib64:/vendor/lib64'
exec '$TMP_ELF'
"

STATUS=$?

exit "$STATUS"

